from __future__ import annotations

from typing import Any

from excel_to_act.steps.conversion_workflow import review_tool_entries


def tool_catalog() -> dict[str, Any]:
    catalog_tools = [
        {"name": "step3.agent", "command": "step3 agent", "outputs": ["packaged result-driven host-agent contract"]},
        {"name": "step3.tools", "command": "step3 tools", "outputs": ["commands", "prerequisites", "analysis limits"]},
        {"name": "step3.prepare", "command": "step3 prepare --index INDEX --step1-root ROOT --out DIR [--source-id ID] [--scope SCOPE] [--workflow DIR]", "outputs": ["analysis.json"], "checks": ["Step 2 integrity", "source identity", "scope workbook SHA and sheets", "optional workflow binding and input-boundary gate"]},
        {"name": "step3.input-catalog", "command": "step3 input-catalog --analysis DIR --workflow DIR --targets TARGETS.json --catalog CATALOG.input.json", "outputs": ["stage3/revision-N/input_boundary.json", "input_boundary.md"], "checks": ["scalar/vector/table groups", "source-role and exact-coordinate coverage", "scenario and exact target binding including optional result_kind, units, and axes", "human target handoff follows result_order while machine target-selection order is preserved", "optional source-bound topology evidence", "no cache/value ingestion; closure remains unknown without topology"]},
        {"name": "step3.source-trace", "command": "step3 source-trace --analysis DIR --workflow DIR [--model-scope INPUT.json] --out DIR", "outputs": ["source_candidate_trace.json", "source_candidate_trace.md"], "checks": ["confirmed input-boundary, source, scenario, targets, fields, dependencies, and structural-plan binding", "static candidate union from canonical formula text without Step 4 history", "optional hash-bound Agent-proposed finite coordinate fence with explicit excluded-range frontiers", "all confirmed formula-derived external cuts remain inside the declared fence", "exact formula-derived external cuts and upstream exclusions", "explicit branch, lookup, dynamic, unsupported, array, and truncation unknowns", "no formula values, cache reads, formula evaluation, or Excel"]},
        {"name": "step3.fields", "command": "step3 fields --analysis DIR", "outputs": ["fields.json", "fields.md"], "checks": ["retained cell coverage", "contiguous literal/formula grouping", "named scalar identity"]},
        {"name": "step3.dependencies", "command": "step3 dependencies --analysis DIR", "outputs": ["dependencies.json"], "checks": ["static A1, range, scoped-name and supported table references", "empty/excluded/unresolved boundaries"]},
        {"name": "step3.profile", "command": "step3 profile --analysis DIR (--trace ACTIVE_TRACE.json | --source-trace SOURCE_CANDIDATE_TRACE.json) --out DIR", "outputs": ["source_family_profile.json or source_candidate_family_profile.json and paired Markdown"], "checks": ["exactly one trace mode", "trace-selected ordinary formulas against canonical inventory text", "deterministic translated-syntax candidates", "candidate mode rechecks current confirmed catalog and static trace binding", "scope-bounded candidates preserve and recheck the model-scope hash and frontier counts", "no formula evaluation or cache use"]},
        {"name": "step3.plan", "command": "step3 plan --analysis DIR [--semantic-map INPUT.json]", "outputs": ["execution_plan.json", "execution_plan.md", "optional semantic_plan.json/semantic_plan.md"], "checks": ["dependency-first SCC blocks", "recurrence candidates", "optional source-family/array mapping coverage"]},
        {"name": "step3.query", "command": "step3 query --analysis DIR --target TARGET [--sheet SHEET] [--offset N] [--limit N] [--out DIR]", "outputs": ["bounded JSON packet", "optional paired query.json/query.md"], "checks": ["exact name, finite cell/range, field ID, or canonical vba:MODULE", "source/run/stage binding", "scope-respecting stored-cell page"]},
        {"name": "step3.trace", "command": "step3 trace --analysis DIR --target TARGET [--sheet SHEET] [--direction upstream|downstream] [--max-depth N] [--max-fields N] [--out DIR]", "outputs": ["bounded JSON packet", "optional paired trace.json/trace.md"], "checks": ["checked dependency direction", "frontier/cycle/unknown boundaries", "field and edge record caps"]},
        {"name": "step3.check", "command": "step3 check --analysis DIR [--spec INPUT.json] [--semantic-plan PLAN.json]", "outputs": ["validation.json", "handoff.json", "handoff.md", "optional model_spec.json/model_spec.md", "optional semantic_check.json/semantic_check.md"], "checks": ["provenance", "coverage", "dependencies", "block order", "optional exact source/structural citations and complete active semantic mapping"]},
        {"name": "step3.report", "command": "step3 report --analysis DIR --design INPUT.json --workflow DIR", "outputs": ["stage3/revision-N/analysis_design.json", "analysis_design.md"], "checks": ["static evidence and design binding", "known-path coverage ledger", "explicit scenario source-literal assertions against formula-mode source cells", "scenario_source_validation ledger", "scenario, scope, options, unknowns, and validation plan"]},
        *review_tool_entries(3),
    ]
    return {
        "schema_version": "step3.tools.v1",
        "prerequisite": "a pass-validated Step 2 index and unchanged Step 1 artifacts",
        "tools": catalog_tools,
        "limits": ["Step 3 prepare/fields/dependencies/plan/query/trace/source-trace/check/profile are static evidence tools; they do not calculate formulas or prove numerical equivalence", "A workflow-bound analysis must submit and separately confirm step3.input-catalog before static source tracing or final semantic design; input_boundary_confirmed keeps Stage 3 next and does not release Step 4", "The input catalog classifies logical scalar/vector/table objects and accounts for retained source coordinates as business inputs, adapter metadata, or explicit source constants; coordinate counts are not logical-variable counts", "Catalog topology evidence is optional. Without a current target-bound trace, reachability and formula closure remain unknown; a prior trace is a historical lead only", "The source-candidate trace is a conservative source-only branch union. It records unresolved conditional selection, lookup rows, dynamic/broken/unsupported references, arrays, exclusions, and truncation; candidate coverage is not active closure", "An optional model-scope fence is Agent-proposed, source/run/scenario/analysis/catalog/full-trace hash-bound, and cannot omit confirmed formula-derived input cuts; clipped ranges are reported as explicit frontiers and remain unknown", "Proposed formula starts are separate candidate roots, not target starts or proven active paths; model-scope candidate closure and active readiness remain unknown", "Formula-derived external inputs are boundary metadata only until an approved fresh capture or user-supplied rate file is separately bound; formula caches are never accepted", "step3 profile accepts one of an active Step 4 trace or a confirmed Step 3 source-candidate trace; candidate profiles are syntactic and remain closure-unknown", "The semantic-map check proves exact address coverage against its hash-bound selected trace/profile; static-candidate selection never releases generation or proves runtime behavior", "step3 report verifies only explicitly authored source-cell/literal assertions using formula-mode source cells and records them in scenario_source_validation; it does not infer scenario values", "step3 report writes the analysis/design checkpoint only; it does not generate code or call native Excel", "Generation is a separate Step 4 tool; generated code validation and native Excel reconciliation are separate Step 5 actions", "No all-configuration, full-workbook, or GPU readiness claim", "Formula caches are never numeric execution inputs", "Query pages default to 100 and are capped at 500 stored cells; no blank cells are invented", "Trace defaults to depth 4 and 100 fields, caps at 500 fields, 500 edge/boundary records, and 500 displayed frontier entries (extra frontier counts/examples are summarized)", "VBA query returns canonical static inventory source only; VBA is never executed or assigned worksheet ownership", "Spec facts must match current canonical inventory/fields/dependencies; inferred/pending details remain unverified", "Axes inferred from cell geometry remain unconfirmed", "Dynamic/broken references remain explicit"],
        "review_workflow": [
            "workflow status --workflow DIR",
            "workflow confirm --workflow DIR --stage 3 --reviewer agent|human --decision approve --message TEXT",
            "workflow reject --workflow DIR --stage 3 --reviewer agent|human|typesafe --return-to 1|2|3 --message TEXT [--evidence REVIEW.json]",
            "workflow delegate --workflow DIR --authorization AUTH.json",
            "workflow typesafe --workflow DIR --stage 3 --request REQUEST.json (live API call; writes the review evidence)",
            "workflow confirm --workflow DIR --stage 3 --reviewer typesafe --decision approve --message TEXT --evidence REVIEW.json",
            "The human receipt may be recorded only after an explicit user response; do not infer or fabricate approval.",
            "The input-boundary subgate always requires both Agent and actual human approval; TypeSafe cannot substitute there. For final design and stages 4–6, TypeSafe may replace the human only under an explicitly registered matching authorization; it remains a separate reviewer and requires an exact current-artifact decision packet.",
        ],
    }
